-- Phase 8 Part 3: facility fees and deposits (charged to the unit ledger).
-- Generated by prisma migrate diff, followed by a hand-written section.

-- AlterTable
ALTER TABLE "facilities" ADD COLUMN     "deposit_charge_type_id" UUID,
ADD COLUMN     "deposit_minor" BIGINT,
ADD COLUMN     "fee_charge_type_id" UUID,
ADD COLUMN     "fee_per_slot_minor" BIGINT;

-- AlterTable
ALTER TABLE "facility_bookings" ADD COLUMN     "deposit_minor" BIGINT NOT NULL DEFAULT 0,
ADD COLUMN     "deposit_released_at" TIMESTAMPTZ(3),
ADD COLUMN     "fee_minor" BIGINT NOT NULL DEFAULT 0,
ADD COLUMN     "invoice_id" UUID;

-- CreateIndex
CREATE UNIQUE INDEX "facility_bookings_organisation_id_property_id_invoice_id_key" ON "facility_bookings"("organisation_id", "property_id", "invoice_id");

-- AddForeignKey
ALTER TABLE "facilities" ADD CONSTRAINT "facilities_organisation_id_property_id_fee_charge_type_id_fkey" FOREIGN KEY ("organisation_id", "property_id", "fee_charge_type_id") REFERENCES "charge_types"("organisation_id", "property_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "facilities" ADD CONSTRAINT "facilities_organisation_id_property_id_deposit_charge_type_fkey" FOREIGN KEY ("organisation_id", "property_id", "deposit_charge_type_id") REFERENCES "charge_types"("organisation_id", "property_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;

-- AddForeignKey
ALTER TABLE "facility_bookings" ADD CONSTRAINT "facility_bookings_organisation_id_property_id_invoice_id_fkey" FOREIGN KEY ("organisation_id", "property_id", "invoice_id") REFERENCES "invoices"("organisation_id", "property_id", "id") ON DELETE RESTRICT ON UPDATE RESTRICT;



-- =============================================================================================
-- Hand-written below this line: charge types may book to a liability (money held, such as
-- facility deposits); a facility's fee and deposit come with an active charge type of the right
-- kind; each booking keeps the fee and deposit it was made with; the invoice is linked once, to a
-- confirmed booking of the same unit; the deposit is released once, also after the booking has
-- finished. See docs/architecture/DATA_MODEL.md section 8 (Facilities).
-- =============================================================================================

CREATE OR REPLACE FUNCTION app_charge_type_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW."organisation_id", NEW."property_id", NEW."code", NEW."created_at")
     IS DISTINCT FROM (OLD."organisation_id", OLD."property_id", OLD."code", OLD."created_at") THEN
    RAISE EXCEPTION 'charge type % cannot move or change its code', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "ledger_accounts" WHERE "id" = NEW."income_account_id" AND "type" IN ('INCOME', 'LIABILITY')
  ) THEN
    RAISE EXCEPTION 'a charge type books to an income account, or a liability for money held'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

ALTER TABLE "facilities" ADD CONSTRAINT "facilities_charges"
  CHECK (("fee_charge_type_id" IS NULL) = ("fee_per_slot_minor" IS NULL)
         AND ("deposit_charge_type_id" IS NULL) = ("deposit_minor" IS NULL)
         AND ("fee_per_slot_minor" IS NULL OR "fee_per_slot_minor" > 0)
         AND ("deposit_minor" IS NULL OR "deposit_minor" > 0));
ALTER TABLE "facility_bookings" ADD CONSTRAINT "facility_bookings_money"
  CHECK ("fee_minor" >= 0 AND "deposit_minor" >= 0
         AND ("deposit_released_at" IS NULL OR ("invoice_id" IS NOT NULL AND "deposit_minor" > 0)));

-- A fee books to income and a deposit to a liability, through active charge types.
CREATE FUNCTION app_facility_charges_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."fee_charge_type_id" IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW."fee_charge_type_id" IS DISTINCT FROM OLD."fee_charge_type_id")
     AND NOT EXISTS (SELECT 1 FROM "charge_types" c JOIN "ledger_accounts" a ON a."id" = c."income_account_id"
                      WHERE c."id" = NEW."fee_charge_type_id" AND c."status" = 'ACTIVE' AND a."type" = 'INCOME') THEN
    RAISE EXCEPTION 'a facility fee is charged through an active charge type that books to income'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."deposit_charge_type_id" IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW."deposit_charge_type_id" IS DISTINCT FROM OLD."deposit_charge_type_id")
     AND NOT EXISTS (SELECT 1 FROM "charge_types" c JOIN "ledger_accounts" a ON a."id" = c."income_account_id"
                      WHERE c."id" = NEW."deposit_charge_type_id" AND c."status" = 'ACTIVE' AND a."type" = 'LIABILITY') THEN
    RAISE EXCEPTION 'a facility deposit is charged through an active charge type that books to a liability'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facilities_charges_check"
  BEFORE INSERT OR UPDATE ON "facilities"
  FOR EACH ROW EXECUTE FUNCTION app_facility_charges_check();

-- Runs after "facility_bookings_insert" (triggers fire in name order), once slot_count is set.
CREATE FUNCTION app_facility_booking_money_insert() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  f record;
BEGIN
  SELECT "fee_per_slot_minor", "deposit_minor" INTO f FROM "facilities" WHERE "id" = NEW."facility_id";
  NEW."fee_minor" := coalesce(f."fee_per_slot_minor", 0) * NEW."slot_count";
  NEW."deposit_minor" := coalesce(f."deposit_minor", 0);
  NEW."invoice_id" := NULL;
  NEW."deposit_released_at" := NULL;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_bookings_money_insert"
  BEFORE INSERT ON "facility_bookings"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_money_insert();

-- Runs after "facility_bookings_guard".
CREATE FUNCTION app_facility_booking_money_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF (NEW."fee_minor", NEW."deposit_minor") IS DISTINCT FROM (OLD."fee_minor", OLD."deposit_minor") THEN
    RAISE EXCEPTION 'the fee and deposit of booking % never change', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."invoice_id" IS DISTINCT FROM OLD."invoice_id" THEN
    IF OLD."invoice_id" IS NOT NULL OR NEW."status" <> 'CONFIRMED' OR OLD."fee_minor" + OLD."deposit_minor" = 0
       OR NOT EXISTS (SELECT 1 FROM "invoices" WHERE "id" = NEW."invoice_id" AND "unit_id" = OLD."unit_id"
                                              AND "status" = 'ISSUED') THEN
      RAISE EXCEPTION 'booking % is charged once, when confirmed, by an issued invoice of its unit', OLD."id"
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  IF NEW."deposit_released_at" IS DISTINCT FROM OLD."deposit_released_at" THEN
    IF OLD."deposit_released_at" IS NOT NULL OR NEW."deposit_released_at" IS NULL THEN
      RAISE EXCEPTION 'the deposit of booking % is released once', OLD."id" USING ERRCODE = 'check_violation';
    END IF;
    NEW."deposit_released_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "facility_bookings_money_guard"
  BEFORE UPDATE ON "facility_bookings"
  FOR EACH ROW EXECUTE FUNCTION app_facility_booking_money_guard();

CREATE OR REPLACE FUNCTION app_facility_booking_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text := OLD."status" || '>' || NEW."status";
BEGIN
  -- A finished booking changes no more, except that its deposit may still be released (below).
  IF OLD."status" IN ('REJECTED', 'CANCELLED', 'COMPLETED', 'NO_SHOW') AND NEW."status" IS DISTINCT FROM OLD."status" THEN
    RAISE EXCEPTION 'booking % is % and no longer changes', OLD."id", lower(replace(OLD."status"::text, '_', ' '))
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."facility_id", NEW."unit_id", NEW."booking_number",
      NEW."starts_at", NEW."ends_at", NEW."slot_count", NEW."purpose", NEW."booked_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."facility_id", OLD."unit_id", OLD."booking_number",
      OLD."starts_at", OLD."ends_at", OLD."slot_count", OLD."purpose", OLD."booked_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'booking % cannot change place or time; cancel it and book again', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  PERFORM app_facility_lock(OLD."facility_id");
  NEW."decided_by_user_id" := OLD."decided_by_user_id";
  NEW."decided_at" := OLD."decided_at";
  NEW."cancelled_at" := OLD."cancelled_at";

  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    RETURN NEW;
  END IF;
  IF transition NOT IN ('PENDING>CONFIRMED', 'PENDING>REJECTED', 'PENDING>CANCELLED',
                        'CONFIRMED>CANCELLED', 'CONFIRMED>COMPLETED', 'CONFIRMED>NO_SHOW') THEN
    RAISE EXCEPTION 'a booking cannot go from % to %', lower(OLD."status"::text), lower(replace(NEW."status"::text, '_', ' '))
      USING ERRCODE = 'check_violation';
  END IF;
  IF transition IN ('PENDING>REJECTED', 'CONFIRMED>CANCELLED') AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'give a reason to % this booking', CASE NEW."status" WHEN 'REJECTED' THEN 'reject' ELSE 'cancel' END
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" NOT IN ('REJECTED', 'CANCELLED') THEN
    NEW."status_note" := NULL;
  END IF;
  IF transition = 'PENDING>CONFIRMED' AND now() >= OLD."ends_at" THEN
    RAISE EXCEPTION 'this booking has already ended' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."status" IN ('COMPLETED', 'NO_SHOW') AND now() < OLD."starts_at" THEN
    RAISE EXCEPTION 'a booking is marked used or not used once it has started' USING ERRCODE = 'check_violation';
  END IF;

  IF OLD."status" = 'PENDING' AND NEW."status" IN ('CONFIRMED', 'REJECTED') THEN
    NEW."decided_by_user_id" := app_current_user_id();
    NEW."decided_at" := now();
    IF NEW."decided_by_user_id" IS NULL THEN
      RAISE EXCEPTION 'a booking is approved or rejected by a person' USING ERRCODE = 'check_violation';
    END IF;
  ELSIF NEW."status" = 'CANCELLED' THEN
    NEW."cancelled_at" := now();
  END IF;
  RETURN NEW;
END
$$;

